import{_ as e,c as i,o as s,a6 as o}from"./chunks/framework.BY05barL.js";const n="/ucasal-ssoo-estudio/assets/2-asignacion-memoria.D6YzrLP5.png",r="/ucasal-ssoo-estudio/assets/2-mapa-bits.CBKRyE_Y.png",t="/ucasal-ssoo-estudio/assets/2-lista-enlazada.CYouFSwO.png",q=JSON.parse('{"title":"Administración de Memoria","description":"","frontmatter":{},"headers":[],"relativePath":"unidad2/administracion-memoria.md","filePath":"unidad2/administracion-memoria.md"}'),d={name:"unidad2/administracion-memoria.md"};function l(c,a,u,m,p,h){return s(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="administracion-de-memoria" tabindex="-1">Administración de Memoria <a class="header-anchor" href="#administracion-de-memoria" aria-label="Permalink to &quot;Administración de Memoria&quot;">​</a></h1><h3 id="pregunta-2" tabindex="-1">Pregunta 2 <a class="header-anchor" href="#pregunta-2" aria-label="Permalink to &quot;Pregunta 2&quot;">​</a></h3><p>Analice qué tipo de fragmentación se puede generar en un sistema que administra la memoria libre y ocupada con listas enlazadas. ¿Puede encontrar una relación entre la cantidad de huecos (libres) y procesos (ocupado)?.</p><h2 id="espacio-de-direcciones" tabindex="-1">Espacio de Direcciones <a class="header-anchor" href="#espacio-de-direcciones" aria-label="Permalink to &quot;Espacio de Direcciones&quot;">​</a></h2><p><img src="'+n+'" alt="Asignación de Memoria"></p><p>Cada proceso tiene su propio espacio de direcciones, que puede ser contiguo o no contiguo.</p><h2 id="mapa-de-bits" tabindex="-1">Mapa de Bits <a class="header-anchor" href="#mapa-de-bits" aria-label="Permalink to &quot;Mapa de Bits&quot;">​</a></h2><p><img src="'+r+'" alt="Mapa de Bits"></p><p>Se utiliza un mapa de bits para gestionar la memoria, donde cada bit representa un bloque de memoria (libre u ocupado).</p><h2 id="listas-enlazadas" tabindex="-1">Listas Enlazadas <a class="header-anchor" href="#listas-enlazadas" aria-label="Permalink to &quot;Listas Enlazadas&quot;">​</a></h2><p><img src="'+t+'" alt="Lista Enlazada"></p><p>Se utiliza una lista enlazada para gestionar los bloques de memoria, donde cada nodo representa un bloque (libre u ocupado) con su tamaño y dirección.</p><h2 id="relacion-entre-huecos-y-procesos" tabindex="-1">Relación entre huecos y procesos <a class="header-anchor" href="#relacion-entre-huecos-y-procesos" aria-label="Permalink to &quot;Relación entre huecos y procesos&quot;">​</a></h2><ul><li>A mayor cantidad de procesos, mayor cantidad de huecos (fragmentación externa). <strong>Solución: compactación</strong></li><li>A mayor cantidad de huecos, mayor fragmentación externa. <strong>Solución: compactación</strong></li><li>Aunque las listas enlazadas permiten asignar bloques de memoria más eficientemente, un mayor número de procesos con requerimientos variados puede generar fragmentación externa</li><li>Con listas enlazadas los huecos adyacentes se fusionan, así que nunca hay dos huecos consecutivos: <strong>huecos ≤ procesos + 1</strong>. En régimen estable hay aproximadamente la mitad de huecos que de procesos (regla del 50% de Knuth, citada por Tanenbaum).</li></ul><h2 id="comparaciones" tabindex="-1">Comparaciones <a class="header-anchor" href="#comparaciones" aria-label="Permalink to &quot;Comparaciones&quot;">​</a></h2><h3 id="en-terminos-de-velocidad" tabindex="-1">En términos de velocidad <a class="header-anchor" href="#en-terminos-de-velocidad" aria-label="Permalink to &quot;En términos de velocidad&quot;">​</a></h3><ul><li><h4 id="mapa-de-bits-1" tabindex="-1">Mapa de Bits <a class="header-anchor" href="#mapa-de-bits-1" aria-label="Permalink to &quot;Mapa de Bits&quot;">​</a></h4><ul><li>Si hay pocos procesos, puede ser más rápido encontrar un hueco libre.</li><li>Si hay muchos procesos, puede ser más lento debido a la necesidad de escanear el mapa hasta encontrar un hueco adecuado.</li></ul></li><li><h4 id="listas-enlazadas-1" tabindex="-1">Listas Enlazadas <a class="header-anchor" href="#listas-enlazadas-1" aria-label="Permalink to &quot;Listas Enlazadas&quot;">​</a></h4><ul><li>Se pueden aplicar diferentes optimizaciones para mejorar drásticamente la velocidad de búsqueda, sacrificando espacio y tiempo de mantenimiento/gestión. <ul><li>Mantener una lista de huecos ordenada por tamaño (First Fit, Best Fit, Worst Fit).</li><li>Agregar un índice de huecos libres para acelerar la búsqueda.</li></ul></li></ul></li></ul><h3 id="en-terminos-de-espacio" tabindex="-1">En términos de espacio <a class="header-anchor" href="#en-terminos-de-espacio" aria-label="Permalink to &quot;En términos de espacio&quot;">​</a></h3><ul><li><h4 id="mapa-de-bits-2" tabindex="-1">Mapa de Bits <a class="header-anchor" href="#mapa-de-bits-2" aria-label="Permalink to &quot;Mapa de Bits&quot;">​</a></h4><ul><li>El tamaño de la unidad de asignación es un factor importante. <ul><li>Si la unidad de asignación es pequeña, se requieren muchos bits para mapear tanta memoria, lo que puede consumir mucho espacio.</li><li>Aumentar el tamaño de la unidad de asignación reduce el espacio necesario para el mapa de bits, pero puede aumentar la fragmentación interna.</li></ul></li></ul></li><li><h4 id="listas-enlazadas-2" tabindex="-1">Listas Enlazadas <a class="header-anchor" href="#listas-enlazadas-2" aria-label="Permalink to &quot;Listas Enlazadas&quot;">​</a></h4><ul><li>Si hay pocos procesos, las listas enlazadas podrían ocupar menos espacio que un mapa de bits.</li><li>Si hay muchos procesos, las listas enlazadas podrían ocupar más espacio debido a la sobrecarga de los punteros y la necesidad de almacenar información adicional (tamaño, dirección, estado).</li></ul></li></ul>',19)])])}const g=e(d,[["render",l]]);export{q as __pageData,g as default};
